function schedule(){
const anchor=new Date(todayISO()+'T12:00:00');anchor.setDate(anchor.getDate()-((anchor.getDay()+6)%7)+weekOffset*7);
const weekDays=Array.from({length:7},(_,i)=>{const d=new Date(anchor);d.setDate(d.getDate()+i);return d});
if(!calendarSelectedDate)calendarSelectedDate=todayISO();
const days=calendarMode==='day'?[new Date(calendarSelectedDate+'T12:00:00')]:weekDays;
const isoStart=localDateISO(days[0]),isoEnd=localDateISO(days[days.length-1]);
const label=calendarMode==='day'?days[0].toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long',year:'numeric'}):days[0].toLocaleDateString('ru-RU',{day:'numeric',month:'long'})+' — '+days[6].toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'});
const all=db.lessons.filter(l=>l.date>=isoStart&&l.date<=isoEnd&&l.status!=='cancelled');
const visible=all.filter(l=>calendarClientFilter==='all'||String(l.clientId)===String(calendarClientFilter));
const slots=Array.from({length:60},(_,i)=>8*60+i*15);
const clientOptions=db.clients.map(c=>'<option value="'+htmlSafe(c.id)+'" '+(String(c.id)===String(calendarClientFilter)?'selected':'')+'>'+htmlSafe(c.name)+'</option>').join('');
const options='<div class="calendar-filters"><label>Ученик <select aria-label="Фильтр по ученику" onchange="calendarFilter(this.value)"><option value="all">Все ученики</option>'+clientOptions+'</select></label><label>Перейти к дате <input type="date" aria-label="Дата в календаре" value="'+htmlSafe(calendarMode==='day'?calendarSelectedDate:localDateISO(weekDays[0]))+'" onchange="calendarSelectDate(this.value)"></label><div class="calendar-view-switch" role="group" aria-label="Вид календаря"><button type="button" class="'+(calendarMode==='week'?'active':'')+'" onclick="calendarSetMode(\'week\')">Неделя</button><button type="button" class="'+(calendarMode==='day'?'active':'')+'" onclick="calendarSetMode(\'day\')">День</button></div></div>';
const cells=slots.map(minute=>'<div class="calendar-hour '+(minute%60?'calendar-quarter-label':'')+'">'+minutesToClock(minute)+'</div>'+days.map(d=>{
const ds=localDateISO(d),ls=visible.filter(l=>l.date===ds&&Math.floor(lessonMinutes(l.time)/15)*15===minute).sort((a,b)=>String(a.time).localeCompare(String(b.time)));
return '<div class="calendar-cell '+(ds===todayISO()?'is-today':'')+'" data-date="'+ds+'" data-minute="'+minute+'" ondragover="calendarDragOver(event)" ondragleave="calendarDragLeave(event)" ondrop="calendarDrop(event)" onclick="openLesson(null,\''+ds+'\',\''+minutesToClock(minute)+'\')">'+ls.map(l=>{
const name=htmlSafe(client(l.clientId)?.name||'Ученик'),time=htmlSafe(l.time),duration=Number(l.duration)||60;
return '<button type="button" class="calendar-event '+(l.status==='done'?'event-done':'')+'" '+(l.status==='planned'?'draggable="true" ondragstart="calendarDragStart(event)" ondragend="calendarDragEnd(event)"':'')+' data-lesson-id="'+htmlSafe(l.id)+'" onclick="event.stopPropagation();openLessonByKey(this.dataset.lessonId)" title="'+name+' · '+time+'–'+htmlSafe(minutesToClock(lessonMinutes(l.time)+duration))+'"><span class="event-time">'+time+'–'+htmlSafe(minutesToClock(lessonMinutes(l.time)+duration))+'</span><strong>'+name+'</strong><small>'+htmlSafe(l.type||'Занятие')+'</small></button>'
}).join('')+'</div>'}).join('')).join('');
$('#content').innerHTML='<div class="calendar-top"><div><div class="calendar-kicker">РАСПИСАНИЕ</div><h2 class="calendar-range">'+htmlSafe(label)+'</h2><div class="calendar-summary">'+visible.filter(l=>l.status==='planned').length+' запланировано <span>·</span> '+visible.filter(l=>l.status==='done').length+' проведено</div></div><div class="calendar-actions"><button class="calendar-arrow" onclick="shiftWeek(-1)" aria-label="Предыдущий период">‹</button><button class="calendar-today" onclick="calendarToday()">Сегодня</button><button class="calendar-arrow" onclick="shiftWeek(1)" aria-label="Следующий период">›</button><button class="primary" onclick="openLesson()">＋ Занятие</button></div></div>'+options+'<div class="calendar-shell"><div class="calendar-grid '+(calendarMode==='day'?'calendar-grid-day':'')+'"><div class="calendar-corner"></div>'+days.map(d=>'<button type="button" class="calendar-day-head '+(localDateISO(d)===todayISO()?'is-today':'')+'" onclick="calendarSelectedDate=\''+localDateISO(d)+'\';calendarSetMode(\'day\')" aria-label="Открыть день '+localDateISO(d)+'"><span>'+htmlSafe(d.toLocaleDateString('ru-RU',{weekday:'short'}).replace('.',''))+'</span><b>'+d.getDate()+'</b></button>').join('')+cells+'</div></div><div class="calendar-footnote">Нажми на свободный слот для создания занятия. Запланированное занятие можно перетащить в ячейку с шагом 15 минут (например, 09:30 или 09:45). Занятия вне 08:00–22:59 доступны через карточки учеников.</div>';
}
function minutesToClock(value){const v=Math.max(0,Number(value)||0);return String(Math.floor(v/60)).padStart(2,'0')+':'+String(v%60).padStart(2,'0')}
function openLessonByKey(id){const lesson=db.lessons.find(l=>String(l.id)===String(id));if(lesson)openLesson(lesson.id)}
function calendarDragStart(event){const el=event.currentTarget,lesson=db.lessons.find(l=>String(l.id)===String(el.dataset.lessonId));if(!lesson||lesson.status!=='planned'){event.preventDefault();return}event.stopPropagation();event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',String(lesson.id));el.classList.add('dragging')}
function calendarDragEnd(){document.querySelectorAll('.calendar-cell.drop-target,.calendar-event.dragging').forEach(el=>el.classList.remove('drop-target','dragging'))}
function calendarDragOver(event){if(!event.dataTransfer.types.includes('text/plain'))return;event.preventDefault();event.dataTransfer.dropEffect='move';event.currentTarget.classList.add('drop-target')}
function calendarDragLeave(event){if(!event.currentTarget.contains(event.relatedTarget))event.currentTarget.classList.remove('drop-target')}
function calendarDrop(event){event.preventDefault();event.stopPropagation();const cell=event.currentTarget;cell.classList.remove('drop-target');const id=event.dataTransfer.getData('text/plain'),lesson=db.lessons.find(l=>String(l.id)===String(id));calendarDragEnd();if(!lesson||lesson.status!=='planned')return;const date=cell.dataset.date,minute=Number(cell.dataset.minute);if(!date||!Number.isInteger(minute)||minute<480||minute>=1380||minute%15!==0)return;const time=minutesToClock(minute);if(date===lesson.date&&time===lesson.time)return;const candidate={...lesson,date,time};const conflicts=lessonConflicts(candidate,lesson.id);if(conflicts.length){const detail=conflicts.slice(0,4).map(l=>htmlSafe(client(l.clientId)?.name||'Ученик')+' · '+l.time).join('\n');if(!confirm('В новом слоте уже есть занятия:\n'+detail+'\n\nВсё равно перенести?'))return}const before=lesson.date+' '+lesson.time;lesson.date=date;lesson.time=time;save();schedule();setCloudStatus('Занятие перенесено: '+before+' → '+date+' '+time,'pending')}

function clients(){let rows=db.clients.map(c=>`<tr><td class="person">${c.name}</td><td>${c.phone||'—'}</td><td>${c.package}</td><td>${c.remaining}</td><td><span class="status ${c.remaining>2?'good':'warn'}">${c.remaining>2?'Активен':'Заканчивается'}</span></td><td><button class="link-btn" onclick="openClient(${c.id})">Открыть</button></td></tr>`).join('');$('#content').innerHTML=`<div class="toolbar"><input class="search" id="clientSearch" placeholder="Поиск клиента…" oninput="filterClients()"><button class="primary" onclick="openClient()">＋ Добавить клиента</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Клиент</th><th>Телефон</th><th>Абонемент</th><th>Осталось</th><th>Статус</th><th></th></tr></thead><tbody id="clientRows">${rows}</tbody></table></div>`}
function filterClients(){let q=$('#clientSearch').value.toLowerCase();$$('#clientRows tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none')}
function subscriptionVisualState(s){if(s.paymentStatus==='pending')return {label:'Ожидает оплаты',className:'warn'};if(s.endDate&&s.endDate<todayISO())return {label:'Срок истёк',className:'warn'};if(s.startDate&&s.startDate>todayISO())return {label:'Начнётся позже',className:'good'};if(Number(s.remaining)<=0)return {label:'Занятия закончились',className:'warn'};if(Number(s.remaining)<=2)return {label:'Нужно продлить',className:'warn'};return {label:'Активен',className:'good'}}
function subscriptions(){
const today=todayISO(),pending=db.subscriptions.filter(s=>s.paymentStatus==='pending'),renew=db.subscriptions.filter(s=>s.paymentStatus!=='pending'&&(Number(s.remaining)<=2||(s.endDate&&s.endDate<today)));
const active=db.subscriptions.filter(s=>s.paymentStatus!=='pending'&&Number(s.remaining)>0&&(!s.endDate||s.endDate>=today)&&(!s.startDate||s.startDate<=today));
const rows=db.subscriptions.slice().sort((a,b)=>(b.startDate||'').localeCompare(a.startDate||'')).map(s=>{
 const status=subscriptionVisualState(s),holder=client(s.clientId),consumed=db.lessons.filter(l=>String(l.consumedSubscriptionId)===String(s.id)).length;
 return '<tr><td class="person">'+htmlSafe(holder?.name||'—')+'</td><td>'+htmlSafe(s.name)+'<div class="muted">Проведено: '+consumed+'</div></td><td>'+Number(s.remaining)+' / '+Number(s.total)+'</td><td>'+(s.endDate?dateFmt(s.endDate):'Без срока')+'</td><td>'+fmt(Number(s.price)||0)+'</td><td><span class="status '+status.className+'">'+status.label+'</span></td><td class="finance-actions"><button class="link-btn" data-sub-id="'+htmlSafe(s.id)+'" onclick="openSubscription(this.dataset.subId)">Изменить</button><button class="link-btn" data-sub-id="'+htmlSafe(s.id)+'" onclick="renewSubscription(this.dataset.subId)">Продлить</button></td></tr>'
}).join('');
$('#content').innerHTML='<div class="toolbar"><div class="muted">Каждое продление — новый пакет с отдельной предоплатой и историей занятий.</div><button class="primary" onclick="openSubscription()">＋ Новый абонемент</button></div>'+
'<div class="cards finance-cards"><div class="stat"><div class="label">Действующие оплаченные</div><div class="value">'+active.length+'</div><div class="hint">с остатком занятий</div></div><div class="stat"><div class="label">Требуют продления</div><div class="value">'+renew.length+'</div><div class="hint">остаток ≤ 2 или истёк срок</div></div><div class="stat"><div class="label">Ожидают оплаты</div><div class="value">'+pending.length+'</div><div class="hint">пока нельзя списывать занятия</div></div><div class="stat"><div class="label">Всего пакетов</div><div class="value">'+db.subscriptions.length+'</div><div class="hint">включая завершённые</div></div></div>'+
'<div class="table-wrap"><table class="table"><thead><tr><th>Ученик</th><th>Абонемент</th><th>Остаток</th><th>Срок</th><th>Стоимость</th><th>Статус</th><th>Действия</th></tr></thead><tbody>'+rows+'</tbody></table></div>'
}
function renewSubscription(id){const source=db.subscriptions.find(x=>String(x.id)===String(id));if(!source)return alert('Абонемент не найден.');openSubscription(null,source.id)}

function paymentDate(p){return p.status==='paid'?(p.paidAt||p.date||todayISO()):(p.date||todayISO())}
function paymentOverdue(p){return p.status!=='paid'&&(p.date||todayISO())<todayISO()}
function payments(){
const month=monthISO(),paid=db.payments.filter(p=>p.status==='paid'),pendingRows=db.payments.filter(p=>p.status!=='paid');
const income=paid.filter(p=>paymentDate(p).startsWith(month)).reduce((a,x)=>a+(Number(x.amount)||0),0);
const total=paid.reduce((a,x)=>a+(Number(x.amount)||0),0),pending=pendingRows.reduce((a,x)=>a+(Number(x.amount)||0),0);
const overdue=pendingRows.filter(paymentOverdue),overdueSum=overdue.reduce((a,x)=>a+(Number(x.amount)||0),0);
const rows=db.payments.slice().sort((a,b)=>paymentDate(b).localeCompare(paymentDate(a))).map(p=>{
 const status=paymentOverdue(p)?'Просрочено':p.status==='paid'?'Оплачено':'Ожидает',kind=p.type==='subscription'?'Предоплата абонемента':'Разовая оплата';
 return '<tr data-status="'+(paymentOverdue(p)?'overdue':p.status==='paid'?'paid':'pending')+'" data-search="'+htmlSafe((client(p.clientId)?.name||'')+' '+kind+' '+(p.description||''))+'"><td class="person">'+htmlSafe(client(p.clientId)?.name||'—')+'</td><td>'+dateFmt(paymentDate(p))+'<div class="muted">'+(p.status==='paid'?'Дата получения':'Ожидаемая дата')+'</div></td><td>'+fmt(Number(p.amount)||0)+'</td><td>'+kind+(p.description?'<div class="muted">'+htmlSafe(p.description)+'</div>':'')+'</td><td><span class="status '+(p.status==='paid'?'good':'warn')+'">'+status+'</span></td><td class="finance-actions"><button class="link-btn" data-pay-id="'+htmlSafe(p.id)+'" onclick="togglePaymentStatus(this.dataset.payId)">'+(p.status==='paid'?'Вернуть в ожидание':'Отметить оплату')+'</button> <button class="link-btn" data-pay-id="'+htmlSafe(p.id)+'" onclick="deletePayment(this.dataset.payId)">Удалить</button></td></tr>'
}).join('');
$('#content').innerHTML='<div class="toolbar"><div class="muted">Учитываются фактически полученные деньги. Для ожидаемых оплат отображается предполагаемая дата.</div><div class="finance-actions"><button class="secondary" onclick="exportPaymentsCsv()">↓ Выгрузить CSV</button><button class="primary" onclick="openPayment()">＋ Добавить оплату</button></div></div>'+
'<div class="cards finance-cards"><div class="stat"><div class="label">Получено за месяц</div><div class="value">'+fmt(income)+'</div><div class="hint">по датам поступления</div></div><div class="stat"><div class="label">Получено за всё время</div><div class="value">'+fmt(total)+'</div></div><div class="stat"><div class="label">Ожидает оплаты</div><div class="value">'+fmt(pending)+'</div><div class="hint">'+pendingRows.length+' платежей</div></div><div class="stat"><div class="label">Просрочено</div><div class="value">'+fmt(overdueSum)+'</div><div class="hint">'+overdue.length+' платежей</div></div></div>'+
'<div class="finance-filters"><input id="paymentSearch" class="search" type="search" placeholder="Поиск по ученику и назначению…" aria-label="Поиск оплат" oninput="filterPayments()"><select id="paymentFilter" aria-label="Статус платежа" onchange="filterPayments()"><option value="all">Все платежи</option><option value="paid">Оплаченные</option><option value="pending">Ожидают</option><option value="overdue">Просроченные</option></select></div>'+
'<div class="table-wrap"><table class="table"><thead><tr><th>Ученик</th><th>Дата</th><th>Сумма</th><th>Назначение</th><th>Статус</th><th>Действия</th></tr></thead><tbody id="paymentRows">'+rows+'</tbody></table></div>'
}
function filterPayments(){const query=($('#paymentSearch')?.value||'').trim().toLowerCase(),status=$('#paymentFilter')?.value||'all';$$('#paymentRows tr').forEach(row=>{const match=(!query||(row.dataset.search||'').toLowerCase().includes(query))&&(status==='all'||row.dataset.status===status||(status==='pending'&&row.dataset.status==='overdue'));row.hidden=!match})}
function exportPaymentsCsv(){const esc=value=>{let v=String(value??'');if(/^[=+\-@\t\r]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"'};const rows=[['Ученик','Дата','Сумма, ₽','Назначение','Статус','Дата ожидаемой оплаты']];db.payments.slice().sort((a,b)=>paymentDate(b).localeCompare(paymentDate(a))).forEach(p=>rows.push([client(p.clientId)?.name||'',paymentDate(p),Number(p.amount)||0,p.type==='subscription'?'Предоплата: '+(p.description||''):'Разовая оплата',p.status==='paid'?'Оплачено':'Ожидает',p.date||'']));const blob=new Blob(['\ufeff'+rows.map(row=>row.map(esc).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='teacherpro-payments-'+todayISO()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

function togglePaymentStatus(id){const p=db.payments.find(x=>String(x.id)===String(id));if(!p)return;const next=p.status==='paid'?'pending':'paid';if(next==='paid'&&!confirm('Отметить оплату как полученную?'))return;if(next==='pending'&&p.subscriptionId&&db.lessons.some(l=>String(l.consumedSubscriptionId)===String(p.subscriptionId)))return alert('По этому абонементу уже списывались занятия. Нельзя вернуть предоплату в ожидание, пока есть проведённые занятия.');p.status=next;if(next==='paid')p.paidAt=todayISO();else delete p.paidAt;if(p.subscriptionId){const sub=db.subscriptions.find(x=>String(x.id)===String(p.subscriptionId));if(sub)sub.paymentStatus=next;}save();render()}
function openPayment(){if(!db.clients.length)return alert('Сначала добавь ученика в разделе «Клиенты».');const c=db.clients[0];openModal('Новая оплата','<div class="form"><label>Клиент<select id="pClient" onchange="updatePaymentDefault()">'+db.clients.map(x=>'<option value="'+x.id+'">'+x.name+'</option>').join('')+'</select></label><label>Дата<input id="pDate" type="date" value="'+todayISO()+'"></label><label>Сумма<input id="pAmount" type="number" min="1" step="0.01" value="'+(c.price||'')+'" required></label><label>Статус<select id="pStatus"><option value="paid">Оплачено</option><option value="pending">Ожидает оплаты</option></select></label><div class="form-actions"><button class="secondary" onclick="closeModal()">Отмена</button><button class="primary" onclick="savePayment()">Сохранить</button></div></div>')}
function updatePaymentDefault(){const c=client(+$('#pClient').value);if(c)$('#pAmount').value=c.price||''}
function savePayment(){let amount=+$('#pAmount').value||0;if(amount<=0)return alert('Укажите сумму');const status=$('#pStatus').value;db.payments.push({id:crypto.randomUUID(),clientId:+$('#pClient').value,amount,date:$('#pDate').value||todayISO(),status,type:'single',...(status==='paid'?{paidAt:todayISO()}:{})});save();closeModal();render()}
function deletePayment(id){const p=db.payments.find(x=>String(x.id)===String(id));if(!p)return;if(p.subscriptionId)return alert('Запись предоплаты связана с абонементом. Используй смену статуса в истории оплат; удаление отключено для сохранения финансовой истории.');if(!confirm('Удалить эту запись об оплате?'))return;db.payments=db.payments.filter(x=>String(x.id)!==String(id));save();render()}
function settings(){$('#content').innerHTML='<div class="settings-grid"><div class="setting"><h3>Облачная синхронизация</h3><p>Данные синхронизируются между устройствами после входа в тот же аккаунт.</p><div id="cloudStatus" class="cloud-status">'+(cloudUser?'Облако подключено · '+cloudUser.email:(cloudConfigured()?'Ожидает входа':'Не настроено'))+'</div>'+(cloudUser?'<button class="secondary" onclick="syncCloud()">Синхронизировать сейчас</button> <button class="secondary" onclick="useCloudVersion()">Загрузить облачную версию (с резервной копией)</button> <button class="secondary" onclick="signOutCloud()">Выйти из аккаунта</button>':'<p>Проверь настройки подключения к Supabase.</p>')+'</div><div class="setting"><h3>Профиль</h3><p>Имя отображается в личном интерфейсе.</p><div class="form"><label>Имя<input id="setName" value="'+(db.settings.name||'')+'"></label><button class="primary" onclick="saveSettings()">Сохранить</button></div></div><div class="setting"><h3>Напоминания</h3><p>Автоматическая отправка сообщений пока не подключена.</p><span class="pill">В планах</span></div><div class="setting"><h3>Резервная копия</h3><p>Скачай JSON-файл для восстановления данных. Импорт заменит текущие данные после подтверждения.</p><button class="secondary" onclick="exportData()">Скачать резервную копию</button> <label class="secondary import-label">Импорт JSON<input id="importFile" type="file" accept="application/json,.json" onchange="importData(this)" hidden></label></div><div class="setting"><h3>Опасная зона</h3><p>Удаляет данные приложения в этом аккаунте. Сначала скачай резервную копию.</p><button class="secondary" onclick="resetData()">Очистить все данные</button></div></div>'}
function importData(input){const file=input.files&&input.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const raw=JSON.parse(reader.result);const parsed=normalizeDb(raw.data||raw);if(!confirm('Импортировать резервную копию? Текущие данные будут заменены.'))return;db=parsed;save();render();alert('Резервная копия восстановлена.')}catch(e){alert('Не удалось прочитать файл. Выбери резервную копию TeacherPro в формате JSON.')}finally{input.value=''}};reader.readAsText(file)}
function saveSettings(){db.settings.name=$('#setName')?.value||db.settings.name;db.settings.specialistMode=$('#mode')?.checked??db.settings.specialistMode;save();render()}
function openSubscription(id,sourceId){
if(!db.clients.length){alert('Сначала добавь ученика.');setPage('clients');return}
const editing=id?db.subscriptions.find(s=>String(s.id)===String(id)):null,source=!editing&&sourceId?db.subscriptions.find(s=>String(s.id)===String(sourceId)):null;
if(id&&!editing)return alert('Абонемент не найден.');
const x=editing||{clientId:source?.clientId||db.clients[0].id,name:source?.name||'8 занятий',total:source?.total||8,remaining:source?.total||8,price:source?.price??7200,startDate:todayISO(),endDate:'',paymentStatus:'paid'};
const consumed=editing?db.lessons.filter(l=>String(l.consumedSubscriptionId)===String(editing.id)).length:0;
const html='<div class="form"><label>Ученик<select id="sClient" '+(editing?'disabled':'')+'>'+db.clients.map(c=>'<option value="'+htmlSafe(c.id)+'" '+(String(c.id)===String(x.clientId)?'selected':'')+'>'+htmlSafe(c.name)+'</option>').join('')+'</select></label>'+
'<label>Название<input id="sName" value="'+htmlSafe(x.name||'')+'"></label><label>Всего занятий<input id="sTotal" type="number" min="1" step="1" value="'+Number(x.total||1)+'"></label>'+
'<label>Осталось занятий<input id="sRemain" type="number" min="0" step="1" value="'+Number(x.remaining??0)+'"></label>'+
(editing?'<p class="muted">Уже списано по этому пакету: '+consumed+' занятий. Нельзя уменьшить пакет ниже использованного.</p>':'')+
'<label>Стоимость абонемента, ₽<input id="sPrice" type="number" min="0" step="0.01" value="'+Number(x.price||0)+'"></label>'+
'<label>Начало действия / ожидаемая оплата<input id="sStart" type="date" value="'+htmlSafe(x.startDate||todayISO())+'"></label><label>Окончание действия<input id="sEnd" type="date" value="'+htmlSafe(x.endDate||'')+'"></label>'+
(!editing?'<label>Статус предоплаты<select id="sPaymentStatus"><option value="paid">Оплачено</option><option value="pending">Ожидается</option></select></label><p class="muted">Продление создаёт новый абонемент и одну связанную запись оплаты. Старый пакет и его история сохраняются.</p>':'<p class="muted">При изменении стоимости или даты обновится существующая связанная оплата, если она есть. Новая запись не создаётся.</p>')+
'<div class="form-actions"><button class="secondary" onclick="closeModal()">Отмена</button><button class="primary" onclick="saveSubscription('+JSON.stringify(editing?.id||null)+')">Сохранить</button></div></div>';
openModal(editing?'Редактирование абонемента':source?'Продление абонемента':'Новый абонемент',html)
}
function saveSubscription(id){
const existing=id?db.subscriptions.find(s=>String(s.id)===String(id)):null;
if(id&&!existing)return alert('Абонемент не найден.');
const total=Number($('#sTotal').value),remaining=Number($('#sRemain').value),price=Number($('#sPrice').value);
const startDate=$('#sStart').value||todayISO(),endDate=$('#sEnd').value||'',name=$('#sName').value.trim()||'Абонемент';
if(!Number.isInteger(total)||total<1||total>1000)return alert('Количество занятий должно быть целым числом от 1 до 1000.');
if(!Number.isInteger(remaining)||remaining<0||remaining>total)return alert('Остаток занятий должен быть целым числом от 0 до общего количества.');
if(!Number.isFinite(price)||price<0||price>100000000)return alert('Укажи корректную стоимость абонемента.');
if(endDate&&endDate<startDate)return alert('Дата окончания не может быть раньше даты начала.');
const consumed=existing?db.lessons.filter(l=>String(l.consumedSubscriptionId)===String(existing.id)).length:0;
if(total<consumed||remaining>total-consumed)return alert('Нельзя уменьшить пакет ниже уже проведённых занятий или увеличить остаток выше неиспользованного количества.');
const status=existing?(existing.paymentStatus||'paid'):($('#sPaymentStatus').value||'paid');
const x={id:existing?.id||'sub-'+crypto.randomUUID(),clientId:existing?.clientId??Number($('#sClient').value),name,total,remaining,price,startDate,endDate,paymentStatus:status,status:remaining>0?'active':'expired'};
if(existing){Object.assign(existing,x);const linked=db.payments.find(p=>String(p.subscriptionId)===String(existing.id));if(linked){linked.amount=price;linked.date=startDate;linked.description='Предоплата: '+name;}}
else{db.subscriptions.push(x);db.payments.push({id:crypto.randomUUID(),clientId:x.clientId,amount:price,date:startDate,status,type:'subscription',subscriptionId:x.id,description:'Предоплата: '+name,...(status==='paid'?{paidAt:todayISO()}:{})})}
syncClientSubscription(x);save();closeModal();render()
}

function syncClientSubscription(x){
const c=client(x.clientId);if(!c)return;
const all=db.subscriptions.filter(s=>String(s.clientId)===String(c.id));
const eligible=all.filter(s=>s.paymentStatus!=='pending'&&Number(s.remaining)>0&&(!s.endDate||s.endDate>=todayISO())&&(!s.startDate||s.startDate<=todayISO())).sort((a,b)=>(a.endDate||'9999-12-31').localeCompare(b.endDate||'9999-12-31'));
const latest=all.slice().sort((a,b)=>(b.startDate||'').localeCompare(a.startDate||''))[0];
const selected=eligible[0]||latest||x;
c.package=selected.name;c.remaining=selected.remaining;c.price=selected.price;c.status=Number(selected.remaining)>2?'active':Number(selected.remaining)>0?'ending':'inactive';
}

function openClient(id){
  if(!id){openModal('Новый ученик','<div class="form"><label>Имя<input id="fName" required placeholder="Имя ученика"></label><label>Телефон<input id="fPhone" type="tel" placeholder="Номер телефона"></label><label>Заметка<textarea id="fNote" placeholder="Цель, особенности, договорённости"></textarea></label><div class="form-actions"><button class="secondary" onclick="closeModal()">Отмена</button><button class="primary" onclick="saveClient(null)">Добавить ученика</button></div></div>');return}
  const c=client(id);if(!c)return;
  const lessons=db.lessons.filter(l=>String(l.clientId)===String(id)).sort((a,b)=>((b.date||'')+(b.time||'')).localeCompare((a.date||'')+(a.time||'')));
  const pays=db.payments.filter(p=>String(p.clientId)===String(id)).sort((a,b)=>paymentDate(b).localeCompare(paymentDate(a)));
  const paid=pays.filter(p=>p.status==='paid').reduce((sum,p)=>sum+(Number(p.amount)||0),0);
  const pending=pays.filter(p=>p.status!=='paid').reduce((sum,p)=>sum+(Number(p.amount)||0),0);
  const next=lessons.filter(l=>l.date>=todayISO()&&l.status==='planned').sort((a,b)=>((a.date||'')+(a.time||'')).localeCompare((b.date||'')+(b.time||'')))[0];
  const subs=db.subscriptions.filter(x=>String(x.clientId)===String(id)).sort((a,b)=>(a.endDate||'9999-12-31').localeCompare(b.endDate||'9999-12-31'));
  const active=subs.find(x=>x.status!=='expired'&&Number(x.remaining)>0);
  const history='<div class="client-profile-summary"><div class="client-profile-stat"><small>Получено</small><strong>'+fmt(paid)+'</strong></div><div class="client-profile-stat"><small>Ожидает оплаты</small><strong>'+fmt(pending)+'</strong></div><div class="client-profile-stat"><small>Занятий проведено</small><strong>'+lessons.filter(l=>l.status==='done').length+'</strong></div></div>'+
    '<div class="client-profile-next"><span>🗓️</span><div><small>Ближайшее занятие</small><strong>'+(next?dateFmt(next.date)+' · '+next.time:'Пока не запланировано')+'</strong></div>'+(next?'<button class="link-btn" onclick="closeModal();openLessonByKey(this.dataset.lessonId)" data-lesson-id="'+htmlSafe(next.id)+'">Открыть</button>':'<button class="link-btn" onclick="closeModal();openLesson()">Запланировать</button>')+'</div>'+
    '<div class="client-profile-sub"><div><small>Текущий абонемент</small><strong>'+(active?active.name:'Не выбран')+'</strong><span>'+(active?('Осталось '+active.remaining+' из '+active.total+' занятий'+(active.endDate?' · до '+dateFmt(active.endDate):'')):'Оформи абонемент, чтобы отслеживать остаток')+'</span></div><button class="secondary" onclick="closeModal();openSubscription()"> '+(active?'Новый абонемент':'Оформить')+' </button></div>'+
    '<div class="client-history"><h3>История занятий</h3>'+(lessons.length?lessons.slice(0,8).map(l=>'<div class="history-row"><span>'+dateFmt(l.date)+' · '+l.time+' · '+(Number(l.duration)||60)+' мин.</span><span class="pill">'+(l.status==='done'?'Проведено':l.status==='cancelled'?'Отменено':'Запланировано')+'</span></div>').join(''):'<p class="muted">Занятий пока нет</p>')+'<h3>История оплат</h3>'+(pays.length?pays.slice(0,8).map(p=>'<div class="history-row"><span>'+dateFmt(p.date||todayISO())+' · '+(p.status==='paid'?'Оплачено':'Ожидает')+'</span><strong>'+fmt(Number(p.amount)||0)+'</strong></div>').join(''):'<p class="muted">Оплат пока нет</p>')+'</div>';
  openModal('Карточка ученика','<div class="form"><label>Имя<input id="fName" value="'+(c.name||'')+'" required></label><label>Телефон<input id="fPhone" type="tel" value="'+(c.phone||'')+'"></label><label>Заметки<textarea id="fNote" placeholder="Цели, особенности, договорённости">'+(c.note||'')+'</textarea></label><div class="form-actions"><button class="secondary" onclick="deleteClient('+id+')">Удалить ученика</button><button class="secondary" onclick="closeModal()">Закрыть</button><button class="primary" onclick="saveClient('+id+')">Сохранить</button></div>'+history+'</div>');
}
function saveClient(id){const name=$('#fName').value.trim();if(!name)return alert('Укажи имя ученика');if(id){Object.assign(client(id),{name,phone:$('#fPhone').value.trim(),note:$('#fNote').value.trim()})}else{db.clients.push({id:Date.now(),name,phone:$('#fPhone').value.trim(),note:$('#fNote').value.trim(),package:'',remaining:0,price:0,status:'active'})}save();closeModal();render()}
function deleteClient(id){if(!confirm('Удалить ученика вместе с его занятиями, абонементами и оплатами? Это действие нельзя отменить.'))return;db.clients=db.clients.filter(c=>c.id!=id);db.lessons=db.lessons.filter(l=>l.clientId!=id);db.payments=db.payments.filter(p=>p.clientId!=id);db.subscriptions=db.subscriptions.filter(s=>s.clientId!=id);save();closeModal();render()}
function lessonMinutes(time){const p=(time||'00:00').split(':').map(Number);return (p[0]||0)*60+(p[1]||0)}
function lessonConflicts(candidate,ignoreId){const start=lessonMinutes(candidate.time),end=start+(Number(candidate.duration)||60);return db.lessons.filter(x=>String(x.id)!==String(ignoreId)&&x.date===candidate.date&&x.status!=='cancelled'&&start<lessonMinutes(x.time)+(Number(x.duration)||60)&&lessonMinutes(x.time)<end)}
function openLesson(id,prefillDate,prefillTime){if(!db.clients.length){alert('Сначала добавь ученика, затем запланируй занятие.');setPage('clients');return}var l=id?db.lessons.find(function(x){return String(x.id)===String(id);}):{date:prefillDate||todayISO(),time:prefillTime||'17:00',clientId:db.clients[0]?.id||'',type:'Индивидуальное',status:'planned',duration:60};var extra=id?'':'<label>Повторять<select id="lRecurrence"><option value="none">Не повторять</option><option value="weekly">Каждую неделю</option><option value="biweekly">Раз в 2 недели</option></select></label><label>Количество недель<input id="lWeeks" type="number" min="1" max="52" value="4"></label>';var html='<div class="form"><label>Клиент<select id="lClient">'+db.clients.map(function(c){return '<option value="'+c.id+'" '+(c.id==l.clientId?'selected':'')+'>'+c.name+'</option>';}).join('')+'</select></label><label>Дата<input id="lDate" type="date" value="'+l.date+'"></label><label>Время<input id="lTime" type="time" value="'+l.time+'"></label><label>Формат<select id="lType"><option '+(l.type==='Индивидуальное'?'selected':'')+'>Индивидуальное</option><option '+(l.type==='Парное'?'selected':'')+'>Парное</option><option '+(l.type==='Групповое'?'selected':'')+'>Групповое</option></select></label><label>Длительность<select id="lDuration"><option value="30" '+((Number(l.duration)||60)===30?'selected':'')+'>30 минут</option><option value="45" '+((Number(l.duration)||60)===45?'selected':'')+'>45 минут</option><option value="60" '+((Number(l.duration)||60)===60?'selected':'')+'>60 минут</option><option value="90" '+((Number(l.duration)||60)===90?'selected':'')+'>90 минут</option><option value="120" '+((Number(l.duration)||60)===120?'selected':'')+'>120 минут</option></select></label><label>Статус<select id="lStatus"><option value="planned" '+(l.status==='planned'?'selected':'')+'>Запланировано</option><option value="done" '+(l.status==='done'?'selected':'')+'>Проведено</option><option value="cancelled" '+(l.status==='cancelled'?'selected':'')+'>Отменено</option></select></label>'+extra+'<div class="form-actions">'+(id?'<button class="secondary" onclick="deleteLesson('+JSON.stringify(id)+')">Удалить</button>':'')+'<button class="secondary" onclick="closeModal()">Отмена</button><button class="primary" onclick="saveLesson('+(id?JSON.stringify(id):'null')+')">Сохранить</button></div></div>';openModal(id?'Редактировать занятие':'Новое занятие',html)}
function deleteLesson(id){const lesson=db.lessons.find(x=>String(x.id)===String(id));if(!lesson)return;if(!confirm('Удалить занятие из расписания?'))return;if(lesson.status==='done')refundLesson(lesson);db.lessons=db.lessons.filter(x=>String(x.id)!==String(id));save();closeModal();render()}
function saveLesson(id){
  if(!db.clients.length)return alert('Сначала добавь ученика.');
  const previous=id?db.lessons.find(x=>String(x.id)===String(id)):null;
  const l={id:id||Date.now(),clientId:+$('#lClient').value,date:$('#lDate').value,time:$('#lTime').value,type:$('#lType').value,duration:+$('#lDuration').value||60,status:$('#lStatus').value};
  if(!l.date||!l.time)return alert('Укажи дату и время.');
  if(previous&&l.status==='cancelled'&&previous.status!=='cancelled'&&!confirm('Отменить занятие? Если оно было списано с абонемента, занятие вернётся в остаток.'))return;
  const mode=previous?'none':($('#lRecurrence')?.value||'none');
  const weeks=previous?1:Math.min(52,Math.max(1,+$('#lWeeks')?.value||4));
  const candidates=[];
  for(let i=0;i<(mode==='none'?1:weeks);i++){
    const d=new Date(l.date+'T00:00:00');d.setDate(d.getDate()+7*i*(mode==='biweekly'?2:1));
    candidates.push({...l,id:i===0?l.id:crypto.randomUUID(),date:d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'),status:i===0?l.status:'planned',recurrence:mode});
  }
  const conflicts=candidates.flatMap((candidate,i)=>candidate.status==='cancelled'?[]:lessonConflicts(candidate,i===0?id:null).map(existing=>({candidate,existing})));
  if(conflicts.length){
    const unique=[...new Map(conflicts.map(x=>[String(x.existing.id),x.existing])).values()];
    const detail=unique.slice(0,5).map(x=>dateFmt(x.date)+' · '+x.time+' · '+(client(x.clientId)?.name||'Ученик')).join('\n');
    if(!confirm('Обнаружено пересечение по времени:\n'+detail+(unique.length>5?'\n…':'')+'\n\nВсё равно сохранить занятие?'))return;
  }
  if(l.status==='done'&&(!previous||previous.status!=='done'||String(previous.clientId)!==String(l.clientId))){const available=db.subscriptions.some(s=>String(s.clientId)===String(l.clientId)&&s.paymentStatus!=='pending'&&Number(s.remaining)>0&&(!s.endDate||s.endDate>=l.date)&&(!s.startDate||s.startDate<=l.date));const legacy=!db.subscriptions.some(s=>String(s.clientId)===String(l.clientId))&&Number(client(l.clientId)?.remaining)>0;if(!available&&!legacy)return alert('Нельзя отметить занятие проведённым: на дату занятия нет оплаченного остатка. Сначала оформи и оплати абонемент.');}
  const beforeChange=JSON.stringify(db);
  if(previous){
    const wasDone=previous.status==='done',clientChanged=previous.clientId!==l.clientId;
    if(wasDone&&(l.status!=='done'||clientChanged))refundLesson(previous);
    Object.assign(previous,l);
    if((!wasDone||clientChanged)&&l.status==='done'&&!consumeLesson(l.clientId,previous)){db=normalizeDb(JSON.parse(beforeChange));return;}
  }else{
    for(const lesson of candidates){if(lesson.status==='done'&&!consumeLesson(lesson.clientId,lesson)){db=normalizeDb(JSON.parse(beforeChange));return}db.lessons.push(lesson)}
  }
  save();closeModal();render();
}
function consumeLesson(clientId,lesson){if(lesson&&(lesson.consumedSubscriptionId||lesson.consumedClientFallback))return true;const allSubs=db.subscriptions.filter(s=>String(s.clientId)===String(clientId));const sub=allSubs.filter(s=>s.paymentStatus!=='pending'&&Number(s.remaining)>0&&(!s.endDate||!lesson?.date||s.endDate>=lesson.date)&&(!s.startDate||!lesson?.date||s.startDate<=lesson.date)).sort((a,b)=>(a.endDate||'9999-12-31').localeCompare(b.endDate||'9999-12-31'))[0];if(sub){sub.remaining=Math.max(0,Number(sub.remaining)-1);sub.status=sub.remaining?'active':'expired';if(lesson)lesson.consumedSubscriptionId=sub.id;syncClientSubscription(sub);return true}if(allSubs.length){alert(allSubs.some(s=>s.paymentStatus==='pending'&&Number(s.remaining)>0)?'У ученика есть неоплаченный абонемент. Проверь предоплату.':'У ученика закончились оплаченные занятия. Оформи новый абонемент.');return false}const c=client(clientId);if(c&&Number(c.remaining)>0){c.remaining=Math.max(0,Number(c.remaining)-1);c.status=c.remaining>2?'active':c.remaining>0?'ending':'inactive';if(lesson)lesson.consumedClientFallback=true;return true}alert('У ученика нет оплаченного остатка занятий. Оформи абонемент или проверь оплату.');return false;}
function refundLesson(lesson){if(lesson?.consumedSubscriptionId){const sub=db.subscriptions.find(s=>String(s.id)===String(lesson.consumedSubscriptionId));if(sub){sub.remaining=Math.min(Number(sub.total)||Number(sub.remaining)+1,(Number(sub.remaining)||0)+1);sub.status=sub.remaining?'active':'expired';syncClientSubscription(sub)}delete lesson.consumedSubscriptionId;}else if(lesson?.consumedClientFallback){const c=client(lesson.clientId);if(c)c.remaining=(Number(c.remaining)||0)+1;delete lesson.consumedClientFallback;}}
function openModal(t,b){$('#modalTitle').textContent=t;$('#modalBody').innerHTML=b;$('#modal').classList.add('open')}function closeModal(){$('#modal').classList.remove('open')}
function setPage(p){page=p;render()}function exportData(){const blob=new Blob([JSON.stringify({app:'TeacherPro',version:1,exportedAt:new Date().toISOString(),data:db},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='teacherpro-backup-'+todayISO()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function resetData(){if(confirm('Очистить всех учеников, занятия, абонементы и оплаты в облаке и на этом устройстве? Сначала скачай резервную копию.')){db=emptyDb();save();render()}}
